(function() {
  function parsePriceToCents(priceStr) {
    if (typeof priceStr !== 'string') {
      throw new Error('Price must be a string');
    }
    if (!/^\d+(\.\d{1,2})?$/.test(priceStr)) {
      throw new Error('Invalid price format');
    }
    const parts = priceStr.split('.');
    const yuan = parseInt(parts[0], 10);
    const fen = parts.length > 1 ? parseInt(parts[1].padEnd(2, '0'), 10) : 0;
    return yuan * 100 + fen;
  }

  function validateQuantity(q) {
    if (typeof q !== 'number' || !Number.isInteger(q) || q < 0) {
      throw new Error('Quantity must be a non-negative integer');
    }
  }

  globalThis.total = function(items) {
    if (!Array.isArray(items)) {
      throw new Error('Items must be an array');
    }
    let totalCents = 0;
    for (const item of items) {
      validateQuantity(item.quantity);
      const priceCents = parsePriceToCents(item.price);
      totalCents += priceCents * item.quantity;
    }
    return totalCents;
  };
})();

